#include "warmdebt.hpp"
#include <iostream>
#include <functional>
int main(){int groups=0,asserts=0;auto check=[&](bool b){++asserts;if(!b)throw std::runtime_error("assertion failed");};auto fail=[&](const std::function<void()>&f){try{f();return false;}catch(const std::runtime_error&){return true;}};auto test=[&](const char*n,const std::function<void()>&f){f();++groups;std::cout<<"PASS "<<n<<'\n';};auto run=[](warm::Policy p,std::vector<warm::Request> t,int actual=12){return warm::simulate(t,p,{6,9,12},100,{0,0,actual},2,130);};try{
test("same arrivals cost deadline tradeoff",[&]{std::vector<warm::Request> t(4,{100,2,4});auto a=run(warm::Policy::reactive,t),b=run(warm::Policy::mean_schedule,t),c=run(warm::Policy::margin_schedule,t);check(a.misses==4&&b.misses==4&&c.misses==0);check(a.replica_ticks==60&&b.replica_ticks==78&&c.replica_ticks==84);for(std::size_t i=0;i<t.size();++i)check(a.requests[i].arrival==b.requests[i].arrival&&b.requests[i].arrival==c.requests[i].arrival);});
test("readiness phases remain distinct",[&]{auto r=warm::simulate({{100,2,4}},warm::Policy::margin_schedule,{6,9,12},100,{3,5,4},1,130);auto x=r.replicas[0];check(x.launch==88&&x.download_done==91&&x.load_done==96&&x.ready==100);check(r.requests[0].start==100&&r.requests[0].finish==102);});
test("no traffic reactive avoids schedule waste",[&]{check(run(warm::Policy::reactive,{}).replica_ticks==0);check(run(warm::Policy::margin_schedule,{}).replica_ticks==84);});
test("zero startup clean negative control",[&]{std::vector<warm::Request> t{{100,2,4}};for(auto p:{warm::Policy::reactive,warm::Policy::mean_schedule,warm::Policy::margin_schedule})check(run(p,t,0).misses==0);});
test("surprise burst and unseen startup expose assumption",[&]{check(run(warm::Policy::margin_schedule,{{70,2,4}}).misses==1);check(run(warm::Policy::margin_schedule,{{100,2,4}},30).misses==1);});
test("queue hand calculated FIFO and exact deadline",[&]{auto r=warm::simulate({{0,3,3},{0,2,5},{1,1,5}},warm::Policy::reactive,{},0,{0,0,0},1,10);check(r.misses==0);check(r.requests[0].finish==3&&r.requests[1].finish==5&&r.requests[2].finish==6);check(r.busy_ticks==6&&r.ready_idle_ticks==4);});
test("training separate from heldout and abstention",[&]{check(warm::lead(warm::Policy::mean_schedule,{6,9,12})==9);check(warm::lead(warm::Policy::margin_schedule,{6,9,12})==12);check(fail([&]{warm::lead(warm::Policy::margin_schedule,{});}));check(fail([&]{warm::lead(warm::Policy::mean_schedule,{-1});}));});
test("invalid stage trace and capacity reject",[&]{check(fail([&]{run(warm::Policy::reactive,{{2,1,2},{1,1,2}});}));check(fail([&]{run(warm::Policy::reactive,{{1,0,2}});}));check(fail([&]{warm::simulate({},warm::Policy::reactive,{},0,{-1,0,0},1,10);}));check(fail([&]{warm::simulate({},warm::Policy::reactive,{},0,{0,0,0},0,10);}));});
test("observations beyond horizon bounded cost",[&]{auto r=warm::simulate({{9,10,1}},warm::Policy::reactive,{},0,{0,0,0},1,10);check(r.misses==1&&r.busy_ticks==1&&r.replica_ticks==1&&r.ready_idle_ticks==0);});
test("deterministic repetition and accounting",[&]{for(int i=1;i<30;++i){std::vector<warm::Request> t(i,{100,2,4});auto a=run(warm::Policy::margin_schedule,t),b=run(warm::Policy::margin_schedule,t);check(warm::json(a)==warm::json(b));check(a.busy_ticks+a.ready_idle_ticks==60);check(a.ready_idle_ticks>=0);}});
std::cout<<"SUMMARY groups="<<groups<<" assertions="<<asserts<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
